package com.littlemakers.village.nativeapp;
import android.opengl.*;import java.nio.*;
/** One VBO and draw call per fish; the GPU bends the body/tail and deforms its normals. */
final class FishRenderer {
 private static final String VERTEX="uniform mat4 uMvp;uniform mat3 uNormal;uniform float uTime;attribute vec3 aPosition;attribute vec3 aNormal;attribute float aType;varying vec3 vN;varying vec3 vP;varying float vType;void main(){vec3 p=aPosition;float t=max(0.,-p.x+.12);float phase=uTime*6.+p.x*4.;float slope=.16*(4.*cos(phase)*t*t-2.*sin(phase)*t);p.z+=sin(phase)*t*t*.16;vec3 n=aNormal;n.x-=slope*n.z;vN=normalize(uNormal*n);vP=aPosition;vType=aType;gl_Position=uMvp*vec4(p,1.);}";
 private static final String FRAGMENT="precision mediump float;uniform vec3 uColor;uniform float uDark;varying vec3 vN;varying vec3 vP;varying float vType;void main(){vec3 n=normalize(vN);vec3 l=normalize(vec3(-.35,.8,1.));float d=max(dot(n,l),0.);vec3 base=mix(uColor*.56,uColor,smoothstep(-.18,.22,-vP.y));base=mix(base,vec3(.78,.79,.65),smoothstep(.02,.22,-vP.y)*.65);float rows=floor(vP.y*44.);vec2 cell=vec2(vP.x*32.+mod(rows,2.)*.5,vP.y*44.);float edge=length(fract(cell)-.5);base*=.88+.12*(1.-smoothstep(.25,.46,edge));float gill=abs(vP.x-(.30-.7*vP.y*vP.y));base*=1.-.28*(1.-smoothstep(.008,.025,gill))*step(abs(vP.y),.19);if(vType>.5&&vType<1.5){float ray=.5+.5*sin(vP.x*85.+vP.y*40.);base=uColor*(.58+.18*ray);}if(vType>1.5)base=vType>2.5?vec3(.88,.91,.83):vec3(.025,.035,.029);float spec=pow(max(dot(n,normalize(l+vec3(0.,0.,1.))),0.),40.);vec3 c=base*(.40+.60*d)+vec3(.11)*spec;c=mix(c,c*vec3(.70,.87,.98),uDark*.35);gl_FragColor=vec4(c,1.);}";
 private int program,buffer,count,pos,normal,type,mvpU,normalU,timeU,colorU,darkU;
 private final float[]mvp=new float[16],inverse=new float[16],normals=new float[9];
 private static int compile(int kind,String code){int s=GLES20.glCreateShader(kind);GLES20.glShaderSource(s,code);GLES20.glCompileShader(s);int[]ok={0};GLES20.glGetShaderiv(s,GLES20.GL_COMPILE_STATUS,ok,0);if(ok[0]==0)throw new IllegalStateException(GLES20.glGetShaderInfoLog(s));return s;}
 void create(){int v=compile(GLES20.GL_VERTEX_SHADER,VERTEX),f=compile(GLES20.GL_FRAGMENT_SHADER,FRAGMENT);program=GLES20.glCreateProgram();GLES20.glAttachShader(program,v);GLES20.glAttachShader(program,f);GLES20.glLinkProgram(program);GLES20.glDeleteShader(v);GLES20.glDeleteShader(f);int[]ok={0};GLES20.glGetProgramiv(program,GLES20.GL_LINK_STATUS,ok,0);if(ok[0]==0)throw new IllegalStateException(GLES20.glGetProgramInfoLog(program));pos=GLES20.glGetAttribLocation(program,"aPosition");normal=GLES20.glGetAttribLocation(program,"aNormal");type=GLES20.glGetAttribLocation(program,"aType");mvpU=GLES20.glGetUniformLocation(program,"uMvp");normalU=GLES20.glGetUniformLocation(program,"uNormal");timeU=GLES20.glGetUniformLocation(program,"uTime");colorU=GLES20.glGetUniformLocation(program,"uColor");darkU=GLES20.glGetUniformLocation(program,"uDark");float[]vertices=FishGeometry.build();count=vertices.length/7;FloatBuffer data=ByteBuffer.allocateDirect(vertices.length*4).order(ByteOrder.nativeOrder()).asFloatBuffer();data.put(vertices).position(0);int[]id={0};GLES20.glGenBuffers(1,id,0);buffer=id[0];GLES20.glBindBuffer(GLES20.GL_ARRAY_BUFFER,buffer);GLES20.glBufferData(GLES20.GL_ARRAY_BUFFER,vertices.length*4,data,GLES20.GL_STATIC_DRAW);GLES20.glBindBuffer(GLES20.GL_ARRAY_BUFFER,0);}
 void draw(float[]vp,float[]model,float time,int color,boolean dark){if(program==0||!Matrix.invertM(inverse,0,model,0))return;Matrix.multiplyMM(mvp,0,vp,0,model,0);for(int c=0;c<3;c++)for(int r=0;r<3;r++)normals[c*3+r]=inverse[r*4+c];GLES20.glUseProgram(program);GLES20.glUniformMatrix4fv(mvpU,1,false,mvp,0);GLES20.glUniformMatrix3fv(normalU,1,false,normals,0);GLES20.glUniform1f(timeU,time);GLES20.glUniform1f(darkU,dark?1:0);GLES20.glUniform3f(colorU,((color>>16)&255)/255f,((color>>8)&255)/255f,(color&255)/255f);GLES20.glBindBuffer(GLES20.GL_ARRAY_BUFFER,buffer);GLES20.glEnableVertexAttribArray(pos);GLES20.glEnableVertexAttribArray(normal);GLES20.glEnableVertexAttribArray(type);GLES20.glVertexAttribPointer(pos,3,GLES20.GL_FLOAT,false,28,0);GLES20.glVertexAttribPointer(normal,3,GLES20.GL_FLOAT,false,28,12);GLES20.glVertexAttribPointer(type,1,GLES20.GL_FLOAT,false,28,24);GLES20.glDrawArrays(GLES20.GL_TRIANGLES,0,count);GLES20.glDisableVertexAttribArray(type);GLES20.glBindBuffer(GLES20.GL_ARRAY_BUFFER,0);}
}
